replace('p9-jack-headless-query', ROOT / '✏️s/🔌️plugins/🔱️trinity/🗿️artifacts/🔌️jack/🏅️standards/🔖️1/🪆️subsets/✳️any/✏️editor/🧪️tests/🔬️unit/🦀️.rs', '}\n//#endregion 🤖️AgentLaneLaws\n', '}\n\n/// 🤖️ LAW: the document effect of a Jack query needs no window. An agent, which has none, runs `loadExampleQuery` and\n/// `runQuery` without naming a results window: the example becomes the document\'s query and a CREATE clause changes the\n/// graph on the agent lane exactly as on the shell lane; only a named, attached results window receives the matches. Both\n/// were refused "targeted window transient capture requires an attached window instance" (G12\'s MCP coverage, 2026-09-29).\n#[semio_framework_async_macros::async_test]\nasync fn an_agent_runs_jack_queries_whose_document_effect_needs_no_window() {\n    use semio_framework_plugin::artifact_app_laws::{declared_verb_agent_divergences, declared_verb_probe, declared_verb_staged_wrote_document, declared_verb_wrote_document, probe_agent_lane};\n    let examples = r#"{"verbs":{"loadExampleQuery":{"query":"MATCH (a:Piece) WHERE a.name = \'b\' SET a.label = \'demo-label\'"},"runQuery":{"query":"CREATE (n:Piece)"}}}"#;\n    let probes = probe_agent_lane::<EditorApp<TrinityJackPlayApp>, semio_s_artifact_stdio_semio::SemioMembers>(create_trinity_jack_app, Some(examples), &["loadExampleQuery", "runQuery"]).await;\n    for verb in ["loadExampleQuery", "runQuery"] {\n        let probe = declared_verb_probe(&probes, verb);\n        assert!(declared_verb_wrote_document(probe.agent.as_ref().expect("the query verbs are agent-facing")), "{verb} writes the document on the agent lane: {:?}", probe.agent);\n        assert!(declared_verb_staged_wrote_document(probe), "{verb} writes the document on the shell lane: {:?}", probe.windows);\n    }\n    assert_eq!(declared_verb_agent_divergences(&probes), Vec::<String>::new(), "agent-lane divergences");\n}\n//#endregion 🤖️AgentLaneLaws\n')
