replace('p9-jack-headless-query', ROOT / '✏️s/🔌️plugins/🔱️trinity/🗿️artifacts/🔌️jack/🏅️standards/🔖️1/🪆️subsets/✳️any/✏️editor/🎮️commands/▶️run-query/🧵️job/🧪️tests/🔬️unit/🦀️.rs', '        let rejected = checkpoint(&source);\n        let mut target = JackQueryWork::new("runQuery", "RETURN 1".into(), false, "editor".into(), "results".into(), 700, 21);\n        assert!(<JackQueryWork as ArtifactCommandWork<Owner>>::restore(&mut target, &rejected).is_err());\n    }\n', '        let rejected = checkpoint(&source);\n        let mut target = JackQueryWork::new("runQuery", "RETURN 1".into(), false, Some("editor".into()), Some("results".into()), 700, 21);\n        assert!(<JackQueryWork as ArtifactCommandWork<Owner>>::restore(&mut target, &rejected).is_err());\n    }\n\n    #[test]\n    fn query_checkpoint_restores_a_headless_run_and_refuses_a_half_named_window_pair() {\n        let headless = JackQueryWork::new("loadExampleQuery", "RETURN 1".into(), true, None, None, 900, 3);\n        let bytes = checkpoint(&headless);\n        let mut restored = JackQueryWork::new("loadExampleQuery", "RETURN 1".into(), true, None, None, 900, 3);\n        <JackQueryWork as ArtifactCommandWork<Owner>>::restore(&mut restored, &bytes).expect("a headless run restores");\n        for (editor, results) in [(Some("editor".to_string()), None), (None, Some("results".to_string()))] {\n            let mut half = JackQueryWork::new("loadExampleQuery", "RETURN 1".into(), true, editor, results, 900, 3);\n            assert!(<JackQueryWork as ArtifactCommandWork<Owner>>::restore(&mut half, &bytes).is_err(), "results go to a named pair or nowhere");\n        }\n    }\n')

